        persistLayout();
      }
      if (panelDragSession?.pointerId === event.pointerId) {
        panelDragSession = null;
        panelDragIndicator.style.opacity = ".42";
        panelDragIndicator.style.transform = "scaleX(1)";
        panelDragIndicator.style.boxShadow =
